#include <stdio.h>
#include <stdlib.h>

static int compare_desc(const void *a, const void *b) {
    long long diff = *(const long long *)b - *(const long long *)a;
    if (diff > 0) return 1;
    if (diff < 0) return -1;
    return 0;
}

#define INF 0x3f3f3f3f3f3f3f3fLL

int main() {
    int n, k;
    if (scanf("%d %d", &n, &k) != 2) return 0;

    long long *t = (long long *)malloc((n + 1) * sizeof(long long));
    for (int i = 1; i <= n; i++) {
        scanf("%lld", &t[i]);
    }

    qsort(t + 1, n, sizeof(long long), compare_desc);

    long long *dp_prev = (long long *)malloc((n + 1) * sizeof(long long));
    long long *dp_curr = (long long *)malloc((n + 1) * sizeof(long long));

    for (int i = 0; i <= n; i++) {
        dp_prev[i] = 0;
    }

    for (int j = 1; j <= k; j++) {
        for (int i = 0; i <= n; i++) {
            dp_curr[i] = INF;
        }

        for (int i = 3 * j; i <= n; i++) {
            dp_curr[i] = dp_curr[i - 1];

            long long diff = t[i - 1] - t[i];
            long long cost = diff * diff;

            if (dp_prev[i - 2] != INF) {
                long long candidate = dp_prev[i - 2] + cost;
                if (candidate < dp_curr[i]) {
                    dp_curr[i] = candidate;
                }
            }
        }

        long long *temp = dp_prev;
        dp_prev = dp_curr;
        dp_curr = temp;
    }

    printf("%lld\n", dp_prev[n]);

    free(t);
    free(dp_prev);
    free(dp_curr);

    return 0;
}
